import {gradingSheetModel,sheetPreview,generatePdf,generateXlsx,filename,saveDownload} from './grading-sheet.js';
import {grade,gwa,weightsFor,csv,SCALE} from './grade.js';
import * as vault from './store.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1m0-15c3-2 6-2 9-1v15c-3-1-6-1-9 1V5',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h2M14 14h2M8 18h2',check:'M5 12l4 4L19 6',file:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 7M22 21v-2a4 4 0 0 0-3-4',chart:'M4 3v18h17M8 16v-4M13 16V7M18 16v-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M4 12h15M14 7l5 5-5 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',close:'M6 6l12 12M6 18L18 6',chevron:'M9 5l7 7-7 7',school:'M3 10l9-7 9 7M5 9v12h14V9M10 21v-6h4v6M10 10h4',screen:'M3 4h18v13H3zM12 17v4M8 21h8',code:'M8 6l-6 6 6 6M16 6l6 6-6 6M14 3l-4 18',leaf:'M20 3c-10 0-17 3-16 10 1 7 15 6 16-10M5 18L16 7',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4',lock:'M5 11h14v10H5zM8 11V7a4 4 0 0 1 8 0v4',mail:'M3 5h18v14H3zM3 5l9 8 9-8',edit:'M15 4l5 5M4 20l5-1L21 7l-4-4L5 15z',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const button=(text,action,cls='',ic='')=>`<button class="${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const options=(items,selected)=>items.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('');
const formatGrade=g=>g==null?'—':Number(g).toFixed(2);
const uid=()=>crypto.randomUUID();
const dateString=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateString(new Date());
const dateFmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric'});
const preset=n=>n===1?[{name:'Formative Assessments',weight:25,mode:'formative'},{name:'Long Test 1',weight:25,mode:'average'},{name:'Long Test 2',weight:25,mode:'average'},{name:'Alternative Assessment',weight:25,mode:'average'}]:n===2?[{name:'Formative Assessments',weight:25,mode:'formative'},{name:'Long Test 1',weight:35,mode:'average'},{name:'Alternative Assessment',weight:40,mode:'average'}]:[{name:'Formative Assessments',weight:25,mode:'formative'},{name:'Alternative Assessment',weight:75,mode:'average'}];
function demo(){
 const db={version:1,year:'2026–2027',teacher:'Tom Jordan Secundo',adviserSection:'10-Photon',students:[],classes:[],assignments:[],scores:{},notes:{}};
 const first=['Andrea','Gabriel','Isabel','Miguel','Sofia','Rafael','Bea','Daniel','Elena','Joaquin','Mia','Nico'];const last=['Alvarez','Bautista','Cruz','Dela Rosa','Flores','Garcia','Lim','Mendoza','Navarro','Reyes','Santos','Villanueva'];
 ['10-Photon','10-Graviton','10-Electron','11-Elective'].forEach((section,j)=>{for(let i=0;i<12;i++)db.students.push({id:`s${j}-${i}`,studentId:`DEMO-${j+1}${String(i+1).padStart(3,'0')}`,name:`${last[i]}, ${first[(i+j)%12]}`,section,email:''});});
 ['Computer Science 4','Computer Science 4','Computer Science 4','Computer Science 5','Mathematics 4','English 4'].forEach((name,i)=>{const section=['10-Photon','10-Graviton','10-Electron','11-Elective','10-Photon','10-Photon'][i];const c={id:`c${i}`,name,section,schedule:['Mon, Wed · 9:00–10:00','Tue, Thu · 10:00–11:00','Mon, Fri · 13:00–14:00','Tue, Thu · 14:00–15:00','Mon, Wed · 11:00–12:00','Tue, Fri · 8:00–9:00'][i],units:i===4?1.5:1,base:0,method:'cumulative',teacher:i<4?'self':'colleague',weights:preset(2),quarterWeights:{1:preset(2),2:preset(2),3:preset(3),4:preset(3)},students:db.students.filter(s=>s.section===section).map(s=>s.id)};db.classes.push(c);
 for(let q=1;q<=2;q++)weightsFor(c,q).forEach((w,k)=>{let due=new Date();due.setDate(due.getDate()+(q===1?-45:k===0?-4:k===1?2:5)+i);const a={id:`a${i}-${q}-${k}`,classId:c.id,name:[i<4?'Programming exercises':'Practice exercises',i<4?'Algorithms & logic test':'Long test 1',i<4?'Build a personal website':'Quarter portfolio'][k],points:[20,50,100][k],category:w.name,quarter:q,due:dateString(due),rubric:k===2?[{name:'Accuracy & understanding',points:40},{name:'Application & execution',points:40},{name:'Clarity & presentation',points:20}]:[]};db.assignments.push(a);db.scores[a.id]={};c.students.forEach((id,n)=>{const missing=q===2&&k===0&&(n+i)%7===0;const pending=q===2&&k>0&&n>8;db.scores[a.id][id]={score:missing||pending?null:Math.round(a.points*((n+i)%9===0?.48:.72+((n*3+i+k)%25)/100)),status:missing?'missing':pending?'unsubmitted':'submitted'};});});});return db;
}
let profileId=null,profileReturn='dashboard';
let db=demo(),view='dashboard',role='teacher',quarter=2,classId='c0',classTab='record',sectionFilter='all',query='',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),meeting=false,importBook=null,importRows=[],importPreview=[],rubrics=[];
const classes=()=>role==='teacher'?db.classes.filter(c=>c.teacher==='self'):role==='adviser'?db.classes.filter(c=>c.section===db.adviserSection):db.classes;
const currentClass=()=>db.classes.find(c=>c.id===classId)||db.classes[0];
const assignments=c=>db.assignments.filter(a=>(!c||a.classId===c.id)&&a.quarter===quarter);
const student=id=>db.students.find(s=>s.id===id);
const initials=name=>name.replace(/,/g,'').split(' ').slice(0,2).map(n=>n[0]).join('');
const matches=s=>!query||`${s.name} ${s.studentId}`.toLowerCase().includes(query.toLowerCase());
const received=r=>['submitted','late','excused'].includes(r?.status);
function missingFor(id,cset=classes()){return assignments().filter(a=>cset.some(c=>c.id===a.classId&&c.students.includes(id))&&a.due<today()&&!received(db.scores[a.id]?.[id]));}
function allStudents(cset=classes()){return db.students.filter(s=>cset.some(c=>c.students.includes(s.id)));}
function attention(cset=classes()){return allStudents(cset).map(s=>({s,missing:missingFor(s.id,cset),low:cset.filter(c=>c.students.includes(s.id)&&((grade(db,c,s.id,quarter).final??grade(db,c,s.id,quarter).grade??0)>=2.75))})).filter(x=>x.missing.length||x.low.length).sort((a,b)=>b.missing.length-a.missing.length);}
function completion(c){const aa=assignments(c);let total=0,done=0;aa.forEach(a=>c.students.forEach(id=>{total++;if(received(db.scores[a.id]?.[id]))done++;}));return {done,total,pct:total?Math.round(done/total*100):0};}
function stats(cset=classes()){const students=allStudents(cset),aa=assignments().filter(a=>cset.some(c=>c.id===a.classId));const total=aa.reduce((n,a)=>n+db.classes.find(c=>c.id===a.classId).students.length,0);const done=aa.reduce((n,a)=>n+db.classes.find(c=>c.id===a.classId).students.filter(id=>received(db.scores[a.id]?.[id])).length,0);return {students:students.length,classes:cset.length,rate:total?Math.round(done/total*100):0,attention:attention(cset).length};}
async function save(message){try{await vault.save(db);if(message)toast(message);}catch(e){toast(e.message);}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function navigate(next){view=next;query='';document.body.classList.remove('nav-drawer');render();window.scrollTo(0,0);}
function navItem(label,key,ic,count=''){return `<button class="${view===key?'active':''}" data-nav="${key}">${icon(ic)}${label}${count?`<span class="count">${count}</span>`:''}</button>`;}
function render(){document.body.classList.toggle('meeting',meeting);const s=stats();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">p</div><div><strong>pisay<span style="color:#91a988">.</span></strong><small>THE TEACHER WORKSPACE</small></div></div><div class="campus">${icon('school')}<div><strong>PSHS Bicol Region</strong><small>Excellence, one scholar at a time</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav">${navItem('Overview','dashboard','grid')}${navItem('Grading sheet','grading-sheet','file')}${navItem('My classes','classes','book')}${navItem('Assignments','assignments','file')}${navItem('Calendar','calendar','calendar')}${navItem('Submissions','submissions','check',s.attention||'')}</nav><div class="nav-spacer"></div><div class="nav-label">ACADEMIC INSIGHTS</div><nav class="nav">${navItem('Adviser view','adviser','users')}${navItem('Academic overview','supervisor','chart')}${navItem('Reports & exports','reports','download')}</nav><div class="sidebar-bottom"><div class="local-note"><strong>${icon('lock')} Offline-ready workspace</strong>${vault.isEnabled()?'Your local records are encrypted. Changes sync when connected.':'Explore with fictional data. Set up an encrypted vault to save your work.'}<br>${button(vault.isEnabled()?'Storage & sync →':'Set up secure storage →','storage','text-btn')}</div><nav class="nav">${navItem('Settings','settings','settings')}</nav><div class="profile"><div class="avatar">TS</div><div><strong style="font-size:12px">${esc(db.teacher)}</strong><small>Teacher · Class adviser</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')}<span>${esc(({dashboard:'Overview',classes:'My classes',record:'Class record',adviser:'Adviser view',supervisor:'Academic overview',reports:'Reports & exports','student-profile':'Student performance'})[view]||view.charAt(0).toUpperCase()+view.slice(1))}</span></div><div class="top-actions"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span class="saved" id="sync-status"><span class="dot"></span>${esc(vault.status)}</span><span class="year">SY ${esc(db.year)}</span><select id="quarter" aria-label="Grading quarter">${options([1,2,3,4].map(q=>[q,`Quarter ${q}`]),quarter)}</select><select id="role" aria-label="Workspace view">${options([['teacher','Teacher workspace'],['adviser','Class adviser'],['supervisor','CID chief view']],role)}</select></div></header><div class="content">${({'student-profile':studentProfilePage,'grading-sheet':gradingSheetPage,dashboard:dashboard,classes:classesPage,record:recordPage,assignments:assignmentsPage,calendar:calendarPage,submissions:submissionsPage,adviser:adviserPage,supervisor:supervisorPage,reports:reportsPage,settings:settingsPage})[view]?.()||dashboard()}<div class="footer-note">PISAY WORKSPACE · BICOL REGION CAMPUS · ${vault.isEnabled()?'Encrypted personal workspace':'FICTIONAL DEMONSTRATION DATA'} · SY ${esc(db.year)}</div></div></main></div>`;bind();}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stat(label,value,footer,ic,warning=false){return `<div class="stat"><div class="stat-label">${label}${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-footer ${warning?'warn':''}">${footer}</div></div>`;}
function statCards(cset=classes()){const s=stats(cset);return `<div class="stats">${stat('Active classes',s.classes,`<strong>${new Set(cset.map(c=>c.section)).size} sections</strong> this school year`,'book')}${stat('Students',s.students,'Across your selected classes','users')}${stat('Submission rate',s.rate+'%',`<strong>Quarter ${quarter}</strong> · all assigned outputs`,'check')}${stat('Need attention',s.attention,'<strong>Follow up</strong> on grades & submissions','bell',true)}</div>`;}
function illustration(){return `<svg class="illustration" viewBox="0 0 230 150" fill="none" aria-hidden="true"><circle cx="123" cy="92" r="72" fill="#dde8d6"/><path d="M189 139V71M189 104c-32-8-25-33-25-33 26 3 27 29 25 33M190 88c30-6 29-30 29-30-28 0-30 28-29 30" stroke="#8ba77d" stroke-width="2" fill="#b2c6a6"/><rect x="55" y="133" width="103" height="13" rx="3" fill="#8ea87c"/><rect x="48" y="118" width="104" height="13" rx="3" fill="#c5d3b7"/><rect x="64" y="104" width="105" height="12" rx="3" fill="#e2d6ad"/><g transform="rotate(-9 104 70)"><rect x="66" y="25" width="83" height="91" rx="5" fill="#f6f8ed" stroke="#a0b28e"/><path d="M80 47h52M80 58h38M80 78h32M80 90h44" stroke="#b3c1a2" stroke-width="3"/><circle cx="132" cy="94" r="16" fill="#6d8d62"/><path d="M124 94l5 5 10-12" stroke="#fff" stroke-width="2"/></g><path d="M24 79l5-8 4 9 8 3-8 4-3 8-4-8-8-4z" fill="#b8c7a1"/></svg>`;}
function classCard(c,i){const p=completion(c),missing=attention([c]).length;return `<article class="class-card"><div class="class-card-head"><div class="subject-icon ${['','gold','blue','purple'][i%4]}">${icon(c.name.includes('Computer')?'code':'book')}</div><span class="tag">${esc(c.section.split('-')[0])} · Q${quarter}</span></div><h3>${esc(c.name)}</h3><div class="section-name">${esc(c.section)}</div><div class="card-meta"><span>${icon('users')}${c.students.length} students</span><span>${icon('clock')}${esc(c.schedule)}</span></div><div class="progress-label"><span>Submission progress</span><strong>${p.pct}%</strong></div><div class="progress"><div style="width:${p.pct}%"></div></div><div class="card-bottom"><span>${missing?`<span style="color:#b48c60">●</span> ${missing} need attention`:'<span style="color:#7d9d79">●</span> All caught up'}</span><button class="text-btn" data-class="${c.id}">Open class ${icon('arrow')}</button></div></article>`;}
function upcoming(){const list=assignments().filter(a=>classes().some(c=>c.id===a.classId)&&a.due>=today()).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);return `<div class="panel"><div class="panel-title"><h2>Coming up</h2><span class="pill">Q${quarter}</span></div>${list.length?list.map(a=>{const c=db.classes.find(c=>c.id===a.classId),d=new Date(a.due+'T12:00:00');return `<div class="task"><div class="date-box"><small>${d.toLocaleDateString('en',{month:'short'}).toUpperCase()}</small>${d.getDate()}</div><div><h3>${esc(a.name)}</h3><p>${esc(c.section)} · ${esc(c.name)}</p><span class="pill ${a.category.includes('Test')?'amber':''}">${esc(a.category)}</span></div></div>`;}).join(''):'<p class="muted">No upcoming deadlines this quarter.</p>'}${button('View calendar →','calendar','wide-button')}</div>`;}
function attentionPanel(){const list=attention().slice(0,3);return `<div class="panel"><div class="panel-title"><h2>A little extra support</h2>${icon('users')}</div><p class="muted" style="font-size:10px;margin-top:-7px;margin-bottom:7px">Start a conversation. Make a difference.</p>${list.map(({s,missing,low})=>`<div class="attention-row"><div class="avatar">${initials(s.name)}</div><div><strong>${studentLink(s)}</strong><small>${esc(s.section)} · ${missing.length?`${missing.length} missing output${missing.length>1?'s':''}`:`${low.length} subject${low.length>1?'s':''} to review`}</small></div></div>`).join('')||'<p class="muted">No students flagged.</p>'}${button('Review students →','submissions','wide-button')}</div>`;}
function dashboard(){return `${heading('Your teaching, at a glance.','A little clarity for everything on your plate.',button('Add class','add-class','primary','plus'))}<section class="welcome"><div><div class="eyebrow">READY FOR A GOOD DAY</div><h2>Welcome back, ${esc(db.teacher.split(' ')[0])}.</h2><p>Your classes, your scholars, and their next steps.<br>Let’s keep every student moving forward.</p><button class="text-btn welcome-link" data-action="submissions">Review this quarter’s submissions ${icon('arrow')}</button></div>${illustration()}</section>${statCards()}<div class="layout-two"><div><div class="section-title"><h2>My classes <small style="font-size:11px;font-weight:400;margin-left:8px">${classes().length} active</small></h2>${button('View all →','classes','text-btn')}</div><div class="class-grid">${classes().slice(0,4).map(classCard).join('')||empty('Your first class starts here','Add a subject and section to get started.','Add class','add-class')}</div><div class="bottom-banner"><div class="subject-icon">${icon('screen')}</div><div><h3>Ready for your next academic meeting?</h3><p>Turn your class data into a clear, presentation-ready overview.</p></div>${button('Open meeting view →','meeting','')}</div></div><aside class="aside-panels">${upcoming()}${attentionPanel()}</aside></div>`;}
function empty(title,text,label='',action=''){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${label?button(label,action,'primary'):''}</div>`;}
function classesPage(){return `${heading('My classes','A home for every subject and section.',button('Add class','add-class','primary','plus'))}<div class="class-grid">${classes().map(classCard).join('')}</div>`;}
function classSelect(){return `<select id="class-select" aria-label="Select class">${options(db.classes.map(c=>[c.id,`${c.name} · ${c.section}`]),currentClass()?.id)}</select>`;}
function recordPage(){const c=currentClass();if(!c)return empty('No classes yet','Create your first class.','Add class','add-class');const aa=assignments(c);return `${heading(esc(c.name),`${esc(c.section)} · ${esc(c.schedule)} · ${c.students.length} students`,button('Import students','import','', 'upload')+button('Grading sheet','grading-sheet','primary','file')+button('Add assignment','add-assignment','','plus'))}<div class="toolbar">${classSelect()}${button('Class settings','class-settings','','settings')}${button('Export grades','export','','download')}</div><div class="tabs">${['record','assignments','students','quarters'].map(t=>`<button class="${classTab===t?'active':''}" data-tab="${t}">${({record:'Class record',assignments:'Assignments',students:'Students',quarters:'Four-quarter summary'})[t]}</button>`).join('')}</div>${classTab==='assignments'?assignmentList(aa):classTab==='students'?studentTable(c):classTab==='quarters'?quarterTable(c):`<div class="info">Quarter ${quarter} · ${weightsFor(c,quarter).map(w=>`${esc(w.name)} ${w.weight}%`).join(' · ')}<br>Enter scores or open a mark to set submission status and use a rubric. Incomplete work remains provisional; final grades wait for all weighted categories and prior quarters.</div><div class="toolbar"><input class="search" id="search" placeholder="Search student name or ID…" value="${esc(query)}" aria-label="Search students"><small class="muted">${vault.isEnabled()?'Changes save automatically':'Demo mode · enable secure storage to save'}</small></div><div class="table-wrap"><table><thead><tr><th>Student</th>${aa.map(a=>`<th><button class="text-btn" data-edit-assignment="${a.id}">${esc(a.name)}</button><div>${a.points} pts · ${dateFmt(a.due)}</div></th>`).join('')}<th>Weighted %</th><th>Quarter grade</th></tr></thead><tbody>${c.students.map(student).filter(matches).map(s=>{const g=grade(db,c,s.id,quarter);return `<tr><td><strong>${studentLink(s)}</strong><span class="sub">${esc(s.studentId)}</span></td>${aa.map(a=>{const r=db.scores[a.id]?.[s.id];return `<td><input class="score-input" type="number" min="0" max="${a.points}" step="any" value="${r?.score??''}" aria-label="${esc(s.name)} — ${esc(a.name)} score" data-score="${a.id}" data-student="${s.id}"><button class="text-btn score-status" data-mark="${a.id}" data-student="${s.id}">${esc(r?.status||'unsubmitted')}${a.rubric.length?' · rubric':''}</button></td>`;}).join('')}<td>${g.percent==null?'—':g.percent.toFixed(2)}${!g.complete?'<span class="sub">Provisional</span>':''}</td><td class="grade-cell">${formatGrade(g.final)}${g.final==null?`<span class="sub">${esc(g.reason)}</span>`:''}</td></tr>`;}).join('')}</tbody></table>${!c.students.length?empty('Your roster is empty','Import a CSV or Excel file to start recording grades.','Import students','import'):''}</div>`}`;}
function studentTable(c){return `<div class="toolbar">${button('Add student','add-student','primary','plus')}${button('Download CSV template','template','','download')}</div><div class="table-wrap"><table><thead><tr><th>Student ID</th><th>Full name</th><th>Section</th><th>Email</th><th></th></tr></thead><tbody>${c.students.map(student).map(s=>`<tr><td>${esc(s.studentId)}</td><td>${studentLink(s)}</td><td>${esc(s.section)}</td><td>${esc(s.email)||'—'}</td><td><div class="mini-actions"><button data-edit-student="${s.id}">Edit</button><button data-remove-student="${s.id}" class="danger">Unenroll</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function quarterTable(c){return `<div class="info">The Q4 cumulative grade is the annual subject grade. Missing earlier-quarter grades prevent a final result.</div><div class="table-wrap"><table><thead><tr><th>Student</th>${[1,2,3,4].map(q=>`<th>Quarter ${q}</th>`).join('')}<th>Annual grade</th></tr></thead><tbody>${c.students.map(student).map(s=>`<tr><td>${studentLink(s)}</td>${[1,2,3,4].map(q=>`<td>${formatGrade(grade(db,c,s.id,q).final)}</td>`).join('')}<td class="grade-cell">${formatGrade(grade(db,c,s.id,4).final)}</td></tr>`).join('')}</tbody></table></div>`;}
function assignmentList(aa){return `<div class="assignment-list">${aa.map(a=>{const c=db.classes.find(c=>c.id===a.classId);return `<div class="assignment"><div class="subject-icon">${icon('file')}</div><div style="flex:1"><h3>${esc(a.name)}</h3><p>${esc(c.section)} · ${esc(a.category)} · ${a.points} points · Due ${dateFmt(a.due)}${a.rubric.length?' · Rubric attached':''}</p></div><div class="assignment-actions"><button data-edit-assignment="${a.id}">${icon('edit')}<span>Edit</span></button><button class="danger" data-delete-assignment="${a.id}" aria-label="Delete ${esc(a.name)}">${icon('trash')}</button></div></div>`;}).join('')||empty('A fresh quarter','Add your first assignment to this quarter.','Add assignment','add-assignment')}</div>`;}
function sectionSelect(){return `<select class="section-filter" id="section-filter" aria-label="Filter section">${options([['all','All sections'],...Array.from(new Set(db.classes.map(c=>c.section))).map(s=>[s,s])],sectionFilter)}</select>`;}
function assignmentsPage(){return `${heading('Assignments','Plan the work. Keep the marking manageable.',button('Add assignment','add-assignment','primary','plus'))}<div class="toolbar">${sectionSelect()}<span class="muted">Quarter ${quarter}</span></div>${assignmentList(assignments().filter(a=>classes().some(c=>c.id===a.classId)&&(sectionFilter==='all'||db.classes.find(c=>c.id===a.classId).section===sectionFilter)))}`;}
function calendarPage(){const first=new Date(month.getFullYear(),month.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const aa=assignments().filter(a=>sectionFilter==='all'||db.classes.find(c=>c.id===a.classId).section===sectionFilter);return `${heading('Assignment calendar','A clearer picture of what’s due, across every section.',button('Add assignment','add-assignment','primary','plus'))}<div class="toolbar">${sectionSelect()}<small class="muted">Showing Quarter ${quarter} assignments</small></div><div class="calendar-head"><h2>${month.toLocaleDateString('en',{month:'long',year:'numeric'})}</h2><div class="mini-actions">${button('←','prev-month')}${button('Today','today')}${button('→','next-month')}</div></div><div class="calendar">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(d=>`<div class="day-label">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return `<div class="calendar-day ${d.getMonth()!==month.getMonth()?'off':''}"><span class="${dateString(d)===today()?'today-num':''}">${d.getDate()}</span>${aa.filter(a=>a.due===dateString(d)).map(a=>`<button class="calendar-event" data-edit-assignment="${a.id}"><span>${esc(a.name)}<br>${esc(db.classes.find(c=>c.id===a.classId).section)}</span></button>`).join('')}</div>`;}).join('')}</div>`;}
function submissionsPage(){const list=attention().filter(x=>matches(x.s)&&(sectionFilter==='all'||x.s.section===sectionFilter));return `${heading('Student follow-ups','Spot a backlog early. Make room for a conversation.',button('Print report','print-submissions','','file'))}<div class="toolbar">${sectionSelect()}<input class="search" id="search" aria-label="Search students" placeholder="Search student name or ID…" value="${esc(query)}"></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Missing outputs</th><th>Grade concerns</th><th>Intervention</th><th>Follow up</th></tr></thead><tbody>${list.map(({s,missing,low})=>`<tr><td><strong>${studentLink(s)}</strong><span class="sub">${esc(s.section)} · ${esc(s.studentId)}</span></td><td>${missing.length?`<span class="pill amber">${missing.length} overdue</span>`:'—'}${missing.slice(0,2).map(a=>`<span class="sub">${esc(a.name)}</span>`).join('')}</td><td>${low.length?`<span class="pill red">${low.length} subject${low.length>1?'s':''} ≥ 2.75</span><span class="sub">Includes provisional grades</span>`:'—'}</td><td><button class="text-btn" data-note="${s.id}">${db.notes[s.id]?.[quarter]?'View / edit note':'＋ Add note'}</button></td><td><div class="mini-actions"><button data-slip="${s.id}">Call slip</button><button data-email="${s.id}">${icon('mail')} Email</button></div></td></tr>`).join('')}</tbody></table>${!list.length?empty('All caught up','No students match these follow-up criteria.'):''}</div>`;}
function adviserPage(){const cset=db.classes.filter(c=>c.section===db.adviserSection);return `${heading(`${esc(db.adviserSection)} · Adviser view`,'A shared picture of your advisees, across their enrolled subjects.',button(meeting?'Exit presentation':'Present to faculty','meeting','primary','screen'))}<div class="toolbar"><label>Advisory section <select id="advisory-section">${options(Array.from(new Set(db.classes.map(c=>c.section))).map(s=>[s,s]),db.adviserSection)}</select></label>${button('Export adviser summary','export-adviser','','download')}</div>${statCards(cset)}<div class="info">GWA uses subject units and completed quarter grades. It stays blank until all locally enrolled subjects have final grades. This personal workspace does not yet aggregate other teachers’ accounts.</div>${adviserTable(cset)}`;}
function adviserTable(cset){return `<div class="table-wrap"><table><thead><tr><th>Student</th>${cset.map(c=>`<th>${esc(c.name)}<div>${c.units} unit${c.units!==1?'s':''}</div></th>`).join('')}<th>GWA</th><th>Follow-up</th></tr></thead><tbody>${allStudents(cset).map(s=>{const g=gwa(db,cset,s.id,quarter),miss=missingFor(s.id,cset);return `<tr><td><strong>${studentLink(s)}</strong><span class="sub">${esc(s.studentId)}</span></td>${cset.map(c=>`<td>${c.students.includes(s.id)?formatGrade(grade(db,c,s.id,quarter).final):'N/A'}</td>`).join('')}<td class="grade-cell">${formatGrade(g)}${g==null?'<span class="sub">Awaiting grades</span>':''}</td><td>${miss.length?`<span class="pill amber">${miss.length} missing</span>`:'<span class="pill">Up to date</span>'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function supervisorPage(){const cset=db.classes.filter(c=>sectionFilter==='all'||c.section===sectionFilter),at=attention(cset);const grades=cset.flatMap(c=>c.students.map(s=>grade(db,c,s,quarter).final)).filter(v=>v!=null);const ranges=[['1.00–1.50',g=>g<=1.5],['1.75–2.50',g=>g>1.5&&g<=2.5],['2.75–3.00',g=>g>2.5&&g<=3],['4.00–5.00',g=>g>3]];const counts=ranges.map(([,fn])=>grades.filter(fn).length);return `${heading('Academic overview',`Quarter ${quarter} · Curriculum and Instruction Division`,button(meeting?'Exit presentation':'Present to faculty','meeting','primary','screen'))}<div class="toolbar">${sectionSelect()}<span class="muted">Personal workspace preview · no cross-account access</span></div>${statCards(cset)}<div class="settings-grid"><div class="panel"><h2>Quarter grade distribution</h2><p>${grades.length} complete subject grades · incomplete grades excluded</p><div class="bars">${ranges.map(([label],i)=>`<div class="bar" style="height:${counts[i]/Math.max(...counts,1)*110}px;background:${['#91b08a','#b5c3a0','#d8c18e','#ce9c89'][i]}"><strong>${counts[i]}</strong><span>${label}</span></div>`).join('')}</div></div><div class="panel"><h2>Intervention priorities</h2><p>Review flags with subject teachers. These are follow-up indicators, not scholarship decisions.</p>${at.slice(0,4).map(({s,missing,low})=>`<div class="attention-row"><div class="avatar">${initials(s.name)}</div><div><strong>${studentLink(s)} · ${esc(s.section)}</strong><small>${missing.length} missing outputs · ${low.length} grade concerns</small></div></div>`).join('')||'<p>No students flagged.</p>'}</div></div><div class="section-title" style="margin-top:27px"><h2>Section snapshot</h2></div><div class="table-wrap"><table><thead><tr><th>Section</th><th>Students</th><th>Subjects</th><th>Submission rate</th><th>Need attention</th></tr></thead><tbody>${Array.from(new Set(cset.map(c=>c.section))).map(section=>{const s=stats(cset.filter(c=>c.section===section));return `<tr><td>${esc(section)}</td><td>${s.students}</td><td>${s.classes}</td><td>${s.rate}%</td><td>${s.attention}</td></tr>`;}).join('')}</tbody></table></div><div class="section-title" style="margin-top:27px"><h2>Student performance · all students in selected sections</h2></div>${studentDirectory(cset)}`;}
function reportsPage(){return `${heading('Reports & exports','Spend less time formatting, more time supporting students.')}<div class="toolbar">${classSelect()}</div><div class="settings-grid"><div class="panel"><div class="subject-icon">${icon('download')}</div><h2 style="margin-top:18px">Student grade export</h2><p>CSV with full name, section, student ID number, subject, quarter, percentage, grade, and completion status. Preview the fields before exporting.</p>${button('Export CSV','export','primary')}</div><div class="panel"><div class="subject-icon gold">${icon('file')}</div><h2 style="margin-top:18px">Quarterly grading sheet</h2><p>Download the selected quarter’s official-style grading sheet in PDF or Excel, with component calculations and signature blocks.</p>${button('Open grading sheet','print-grades','primary')}</div><div class="panel"><h2>Submission & intervention report</h2><p>See missing outputs, grade concerns, and teacher intervention notes for the current quarter.</p>${button('Print follow-up report','print-submissions')}</div><div class="panel"><h2>Academic meeting</h2><p>Open a presentation view for the faculty or scholarship meeting. Uses the current quarter’s records.</p>${button('Start meeting view','meeting','','screen')}</div></div><div class="info" style="margin-top:23px">The export contains the requested identifiers. Exact compatibility with the official school database awaits its CSV import specification. Incomplete final grades export as blank, with an explicit status.</div>`;}
function settingsPage(){return `${heading('Workspace settings','Your teaching workflow, with the right safeguards.')}<div class="settings-grid"><form class="panel" id="workspace-form"><h2>Teacher profile</h2><label>Teacher name<input name="teacher" value="${esc(db.teacher)}" required></label><label>School year<input name="year" value="${esc(db.year)}" required></label>${button('Save profile','save-profile','primary')}</form><div class="panel"><h2>Encrypted offline storage</h2><p>Records are encrypted with AES-256-GCM in this browser’s IndexedDB. A passphrase derives the key using PBKDF2. The key stays in memory while unlocked.</p><p id="storage-status">${esc(vault.status)}</p><div class="toolbar" style="margin-top:18px">${button(vault.isEnabled()?'Sync now':'Set up secure storage',vault.isEnabled()?'sync':'enable-vault','primary','lock')}${vault.isEnabled()?button('Lock workspace','lock'):''}</div><p>Auto-sync runs while the app is open and online. A conflicting cloud version pauses sync for review; no edits are silently overwritten.</p>${vault.isEnabled()?button('Review cloud version','cloud-review','text-btn'):''}<p><a href="/signin-with-chatgpt?return_to=/index.html" target="_top">Sign in for cloud sync</a></p></div><div class="panel"><h2>Backup & recovery</h2><p>Download an encrypted backup to protect against browser data being cleared. Keep your passphrase somewhere safe: it cannot be recovered.</p><div class="toolbar" style="margin-top:16px">${button('Encrypted backup','backup','','download')}${button('Restore backup','restore','','upload')}</div></div><div class="panel"><h2>Grading reference</h2><p>Based on the supplied Bicol E-Grades workbooks. Schemes are editable per class and quarter. Formative mode uses 40% numeric completion + 60% pooled score; other workbook components average assignment percentages.</p><p>Quarter 1 uses its tentative grade. Q2–Q4 combine ⅔ current and ⅓ previous quarter grade, then use the workbook’s transmutation thresholds. Base 0 and Base 50 are supported.</p><p>Adviser and CID views are currently views of your personal dataset. Shared staff membership, server-enforced school roles, and email-provider delivery are not enabled.</p></div></div>`;}
function bind(){
 if($('#sheet-settings'))$('#sheet-settings').onsubmit=e=>e.preventDefault();
 if($('#sheet-settings'))$('#sheet-settings').onchange=()=>{const f=new FormData($('#sheet-settings'));db.reportSettings={...db.reportSettings,...Object.fromEntries(f)};currentClass().adviser=f.get('adviser');save();$('#sheet-preview').innerHTML=sheetPreview(gradingSheetModel(db,currentClass(),quarter,{...db.reportSettings,adviser:currentClass().adviser,demo:!vault.isEnabled()}));};
 $('#app').onclick=async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.profile){profileId=b.dataset.profile;profileReturn=view;meeting=false;navigate('student-profile');return;}
 if(b.dataset.nav){if(b.dataset.nav==='adviser')role='adviser';else if(b.dataset.nav==='supervisor')role='supervisor';navigate(b.dataset.nav);return;}
 if(b.dataset.class){classId=b.dataset.class;classTab='record';navigate('record');return;}
 if(b.dataset.tab){classTab=b.dataset.tab;render();return;}
 if(b.dataset.editAssignment){assignmentModal(b.dataset.editAssignment);return;}
 if(b.dataset.deleteAssignment){deleteAssignment(b.dataset.deleteAssignment);return;}
 if(b.dataset.mark){markModal(b.dataset.mark,b.dataset.student);return;}
 if(b.dataset.editStudent){studentModal(b.dataset.editStudent);return;}
 if(b.dataset.removeStudent){const id=b.dataset.removeStudent;modal('Unenroll student',`<p>Remove ${esc(student(id).name)} from ${esc(currentClass().name)}? Their student profile and recorded scores will remain available.</p>${button('Unenroll','confirm-remove','danger')}`,()=>{$('[data-action="confirm-remove"]').onclick=()=>{currentClass().students=currentClass().students.filter(s=>s!==id);save('Student unenrolled');close();render();};});return;}
 if(b.dataset.note){noteModal(b.dataset.note);return;}
 if(b.dataset.slip){slipModal(b.dataset.slip);return;}
 if(b.dataset.email){emailModal(b.dataset.email);return;}
 const a=b.dataset.action;if(!a)return;e.preventDefault();
 const actions={'profile-back':()=>navigate(profileReturn),'print-profile':()=>printDoc('Student performance report',profileReport()),'add-class':()=>classModal(),'add-assignment':()=>assignmentModal(),'class-settings':()=>classSettings(),'import':()=>importModal(),'add-student':()=>studentModal(),'export':()=>exportModal(),'template':()=>download('student-import-template.csv',csv([['fullname','section','student_id','email'],['Sample, Student','10-Photon','2026-001','student@example.com']]),'text/csv'),'calendar':()=>navigate('calendar'),'classes':()=>navigate('classes'),'submissions':()=>navigate('submissions'),'storage':()=>vault.isEnabled()?navigate('settings'):vaultModal(),'enable-vault':()=>vaultModal(),'sync':()=>vault.sync(),'lock':()=>vault.lock(),'backup':()=>backup(),'restore':()=>restoreModal(),'cloud-review':()=>cloudReview(),'meeting':()=>{meeting=!meeting;if(meeting){view=role==='supervisor'?'supervisor':'adviser';if(role==='teacher')role='adviser';}render();},'menu':()=>document.body.classList.toggle('nav-drawer'),'prev-month':()=>{month.setMonth(month.getMonth()-1);render();},'next-month':()=>{month.setMonth(month.getMonth()+1);render();},'today':()=>{month=new Date(new Date().getFullYear(),new Date().getMonth(),1);render();},'print-submissions':()=>printSubmissions(),'print-grades':()=>navigate('grading-sheet'),'grading-sheet':()=>navigate('grading-sheet'),'sheet-pdf':()=>exportSheet('pdf'),'sheet-xlsx':()=>exportSheet('xlsx'),'sheet-both':()=>exportSheet('both'),'export-adviser':()=>exportAdviser(),'save-profile':()=>{const f=$('#workspace-form');if(!f.reportValidity())return;db.teacher=f.teacher.value.trim();db.year=f.year.value.trim();save('Profile saved');render();}};
 try{await actions[a]?.();}catch(err){toast(err.message);}
 };
 $('#quarter').onchange=e=>{quarter=+e.target.value;render();};$('#role').onchange=e=>{role=e.target.value;view=role==='teacher'?'dashboard':role==='adviser'?'adviser':'supervisor';render();};
 if($('#class-select'))$('#class-select').onchange=e=>{classId=e.target.value;render();};
 if($('#section-filter'))$('#section-filter').onchange=e=>{sectionFilter=e.target.value;render();};
 if($('#advisory-section'))$('#advisory-section').onchange=e=>{db.adviserSection=e.target.value;save();render();};
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 document.querySelectorAll('[data-score]').forEach(input=>input.onchange=()=>{const a=db.assignments.find(a=>a.id===input.dataset.score),id=input.dataset.student;const value=input.value===''?null:Number(input.value);if(value!==null&&(!Number.isFinite(value)||value<0||value>a.points)){toast(`Score must be between 0 and ${a.points}.`);render();return;}db.scores[a.id]??={};const prev=db.scores[a.id][id];db.scores[a.id][id]={score:value,status:value==null?'unsubmitted':prev?.status==='late'?'late':'submitted'};save();render();});
 if($('#workspace-form'))$('#workspace-form').onsubmit=e=>e.preventDefault();
}
function modal(title,body,setup){vault.setEditing(true);const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button id="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}<div id="modal-error" class="error" hidden></div></div>`;$('#close-modal').onclick=close;if(!m.open)m.showModal();setup?.();}
const close=()=>{vault.setEditing(false);$('#modal').close();};
function formError(message){$('#modal-error').textContent=message;$('#modal-error').hidden=false;}
const formActions=text=>`<div class="modal-actions"><button type="button" id="cancel">Cancel</button><button type="submit" class="primary">${text}</button></div>`;
function wireForm(fn){$('#cancel').onclick=close;$('#dialog-form').onsubmit=async e=>{e.preventDefault();try{await fn(new FormData(e.target));}catch(err){formError(err.message);}};}
function classModal(){modal('Add a class',`<form id="dialog-form"><label>Subject / class name<input name="name" placeholder="e.g. Computer Science 4" required maxlength="100"></label><div class="form-row"><label>Section<input name="section" placeholder="e.g. 10-Photon" required maxlength="60"></label><label>Subject units<input name="units" type="number" min="0.25" step="0.25" value="1" required></label></div><label>Weekly schedule<input name="schedule" placeholder="e.g. Mon, Wed · 9:00–10:00" required maxlength="100"></label><label>Initial grading scheme<select name="preset">${options([[1,'Option 1 · 25 / 25 / 25 / 25'],[2,'Option 2 · 25 / 35 / 40'],[3,'Option 3 · 25 / 75']],2)}</select></label><label class="checkbox"><input type="checkbox" name="adviser">I am the class adviser of this section</label><p>You can change components and weights separately for each quarter in Class settings.</p>${formActions('Create class')}</form>`,()=>wireForm(f=>{const c={id:uid(),name:f.get('name').trim(),section:f.get('section').trim(),schedule:f.get('schedule').trim(),units:+f.get('units'),weights:preset(+f.get('preset')),quarterWeights:{},students:[],teacher:'self',base:0,method:'cumulative'};if(!c.name||!c.section)throw Error('Name and section are required.');db.classes.push(c);if(f.get('adviser'))db.adviserSection=c.section;classId=c.id;view='record';classTab='students';save('Class created');close();render();}));}
function classSettings(){const c=currentClass();if(!c)return;modal('Class & grading settings',`<form id="dialog-form"><div class="form-row"><label>Subject<input name="name" value="${esc(c.name)}" required></label><label>Section<input name="section" value="${esc(c.section)}" required></label></div><label>Weekly schedule<input name="schedule" value="${esc(c.schedule)}" required></label><div class="form-row"><label>Subject units<input name="units" type="number" min="0.25" step="0.25" value="${c.units}" required></label><label>Percentage scale<select name="base">${options([[0,'Base 0'],[50,'Base 50']],c.quarterBases?.[quarter]??c.base)}</select></label></div><h3>Quarter ${quarter} components</h3><p>Weights must total 100%. Renaming an existing component also updates its assignments in this quarter.</p><div id="weight-rows">${weightsFor(c,quarter).map((w,i)=>weightRow(w,i)).join('')}</div><button type="button" id="add-weight" class="text-btn">＋ Add component</button>${formActions('Save settings')}</form>`,()=>{let index=weightsFor(c,quarter).length;$('#add-weight').onclick=()=>$('#weight-rows').insertAdjacentHTML('beforeend',weightRow({name:'',weight:0,mode:'average'},index++));wireForm(f=>{const rows=Array.from(document.querySelectorAll('.weight-edit'));const weights=rows.map(r=>({name:r.querySelector('[name^=component]').value.trim(),weight:+r.querySelector('[name^=weight]').value,mode:r.querySelector('select').value}));if(weights.some(w=>!w.name)||new Set(weights.map(w=>w.name)).size!==weights.length)throw Error('Use a unique name for every component.');if(Math.abs(weights.reduce((s,w)=>s+w.weight,0)-100)>.001)throw Error('Weights must total 100%.');const old=weightsFor(c,quarter);assignments(c).forEach(a=>{const idx=old.findIndex(w=>w.name===a.category);if(idx>=0)a.category=weights[idx].name;});c.name=f.get('name').trim();c.section=f.get('section').trim();c.schedule=f.get('schedule').trim();c.units=+f.get('units');c.quarterBases??={};c.quarterBases[quarter]=+f.get('base');c.quarterWeights??={};c.quarterWeights[quarter]=weights;save('Class settings saved');close();render();});});}
function weightRow(w,i){return `<div class="weight-edit" style="border-bottom:1px solid #e5eadd;padding:10px 0"><div class="form-row"><label>Component<input name="component${i}" value="${esc(w.name)}" required></label><label>Weight %<input name="weight${i}" type="number" min="0" max="100" step="any" value="${w.weight}" required></label></div><label>Calculation<select>${options([['average','Average assignment percentages'],['points','Pooled points percentage'],['formative','Formative: 40% completion + 60% score']],w.mode)}</select></label></div>`;}
function assignmentModal(id){if(!db.classes.length){classModal();return;}const existing=db.assignments.find(a=>a.id===id),a=existing||{classId:currentClass().id,name:'',points:100,quarter,category:weightsFor(currentClass(),quarter)[0].name,due:today(),rubric:[]};rubrics=structuredClone(a.rubric);modal(existing?'Edit assignment':'New assignment',`<form id="dialog-form"><label>Assignment name<input name="name" value="${esc(a.name)}" placeholder="e.g. Build a personal website" required maxlength="150"></label><label>Class<select name="classId" id="assignment-class" ${existing?'disabled':''}>${options(db.classes.map(c=>[c.id,`${c.name} · ${c.section}`]),a.classId)}</select></label><div class="form-row"><label>Quarter<select name="quarter" id="assignment-quarter" ${existing?'disabled':''}>${options([1,2,3,4].map(q=>[q,`Quarter ${q}`]),a.quarter)}</select></label><label>Component<select name="category" id="assignment-category">${options(weightsFor(db.classes.find(c=>c.id===a.classId),a.quarter).map(w=>[w.name,w.name]),a.category)}</select></label></div><div class="form-row"><label>Total points<input name="points" type="number" min="0.01" step="any" value="${a.points}" required></label><label>Due date<input name="due" type="date" value="${a.due}" required></label></div><h3>Marking rubric <small class="muted">optional</small></h3><p>Criteria maxima must add up to the assignment’s total points.</p><div id="rubric-rows"></div><button type="button" id="add-rubric" class="text-btn">＋ Add criterion</button>${formActions(existing?'Save changes':'Create assignment')}</form>`,()=>{renderRubrics();$('#add-rubric').onclick=()=>{readRubrics();rubrics.push({name:'',points:10});renderRubrics();};const categoryOptions=()=>{$('#assignment-category').innerHTML=options(weightsFor(db.classes.find(c=>c.id===$('#assignment-class').value),+$('#assignment-quarter').value).map(w=>[w.name,w.name]),'');};$('#assignment-class').onchange=categoryOptions;$('#assignment-quarter').onchange=categoryOptions;wireForm(f=>{readRubrics();const points=+f.get('points');if(rubrics.length&&(rubrics.some(r=>!r.name||r.points<=0)||Math.abs(rubrics.reduce((s,r)=>s+r.points,0)-points)>.001))throw Error('Give every criterion a name and positive points. Rubric points must equal total points.');if(existing&&Object.values(db.scores[id]||{}).some(r=>r.score>points))throw Error('An existing score exceeds this total. Adjust the scores first.');const updated={...a,id:existing?.id||uid(),name:f.get('name').trim(),classId:existing?a.classId:f.get('classId'),quarter:existing?a.quarter:+f.get('quarter'),category:f.get('category'),points,due:f.get('due'),rubric:rubrics};if(!updated.name)throw Error('Assignment name is required.');if(existing)Object.assign(existing,updated);else db.assignments.push(updated);save('Assignment saved');close();render();});});}
function readRubrics(){rubrics=Array.from(document.querySelectorAll('.rubric-row')).map(r=>({name:r.querySelector('input[type=text]').value.trim(),points:+r.querySelector('input[type=number]').value}));}
function renderRubrics(){$('#rubric-rows').innerHTML=rubrics.map((r,i)=>`<div class="rubric-row"><input type="text" placeholder="Criterion" value="${esc(r.name)}" aria-label="Criterion ${i+1}" required><input type="number" min="0.01" step="any" value="${r.points}" aria-label="Criterion ${i+1} maximum points" required><button type="button" data-remove-rubric="${i}" aria-label="Remove criterion">×</button></div>`).join('');document.querySelectorAll('[data-remove-rubric]').forEach(b=>b.onclick=()=>{readRubrics();rubrics.splice(+b.dataset.removeRubric,1);renderRubrics();});}
function deleteAssignment(id){const a=db.assignments.find(a=>a.id===id);modal('Delete assignment?',`<p>This removes <strong>${esc(a.name)}</strong> and its recorded scores. Quarter grades will be recalculated.</p><div class="modal-actions">${button('Cancel','cancel-delete')}${button('Delete assignment','confirm-delete','danger')}</div>`,()=>{$('[data-action="cancel-delete"]').onclick=close;$('[data-action="confirm-delete"]').onclick=()=>{db.assignments=db.assignments.filter(x=>x.id!==id);delete db.scores[id];save('Assignment deleted');close();render();};});}
function markModal(aid,sid){const a=db.assignments.find(a=>a.id===aid),s=student(sid),r=db.scores[aid]?.[sid]||{score:null,status:'unsubmitted'};modal('Mark assignment',`<form id="dialog-form"><h3>${esc(a.name)}</h3><p>${esc(s.name)} · ${a.points} total points</p><label>Submission status<select name="status">${options(['unsubmitted','submitted','late','missing','excused'].map(s=>[s,s.charAt(0).toUpperCase()+s.slice(1)]),r.status)}</select></label>${a.rubric.map((criterion,i)=>`<label>${esc(criterion.name)} · / ${criterion.points}<input name="rubric${i}" class="rubric-score" type="number" min="0" max="${criterion.points}" step="any" value="${r.rubric?.[i]??''}"></label>`).join('')}<label>Score / ${a.points}<input name="score" id="mark-total" type="number" min="0" max="${a.points}" step="any" value="${r.score??''}"></label><p>A blank score is ungraded. An entered zero is a real score. Excused work is excluded from the calculation. Missing work is not silently assigned zero.</p>${formActions('Save mark')}</form>`,()=>{document.querySelectorAll('.rubric-score').forEach(input=>input.oninput=()=>{const inputs=[...document.querySelectorAll('.rubric-score')];$('#mark-total').value=inputs.every(i=>i.value!=='')?inputs.reduce((n,i)=>n+Number(i.value),0):'';});wireForm(f=>{let status=f.get('status'),score=f.get('score')===''?null:+f.get('score');if(['unsubmitted','excused'].includes(status)&&score!==null)throw Error('Clear the score for unsubmitted or excused work.');db.scores[aid]??={};db.scores[aid][sid]={status,score,rubric:a.rubric.map((_,i)=>f.get('rubric'+i)===''?null:+f.get('rubric'+i))};save('Mark saved');close();render();});});}
function studentModal(id){const s=id?student(id):{name:'',studentId:'',section:currentClass()?.section||'',email:''};modal(id?'Edit student':'Add student',`<form id="dialog-form"><label>Full name<input name="name" value="${esc(s.name)}" placeholder="Surname, Given name" required></label><div class="form-row"><label>Student ID number<input name="studentId" value="${esc(s.studentId)}" required></label><label>Section<input name="section" value="${esc(s.section)}" required></label></div><label>Roster group <small>(optional, for grading sheets)</small><select name="sex">${options([['','Not specified'],['M','Male'],['F','Female']],s.sex||'')}</select></label><label>Email <small>(optional)</small><input name="email" type="email" value="${esc(s.email)}"></label>${formActions('Save student')}</form>`,()=>wireForm(f=>{const item={id:id||uid(),name:f.get('name').trim(),studentId:f.get('studentId').trim(),section:f.get('section').trim(),email:f.get('email').trim(),sex:f.get('sex')||''};if(!item.name||!item.studentId||!item.section)throw Error('Name, section, and ID are required.');if(db.students.some(x=>x.studentId===item.studentId&&x.id!==id))throw Error('That student ID already exists. Use import to enroll an existing student.');if(id)Object.assign(s,item);else{db.students.push(item);currentClass().students.push(item.id);}save('Student saved');close();render();}));}
function importModal(){if(!currentClass())return classModal();importBook=null;importRows=[];importPreview=[];modal('Import students',`<p>Import a roster into <strong>${esc(currentClass().name)} · ${esc(currentClass().section)}</strong>. Select a sheet and map your columns. Existing student IDs are matched, not duplicated.</p><div class="upload">${icon('upload')}<label>Choose CSV or Excel workbook<input id="import-file" type="file" accept=".csv,.xlsx"></label><small class="muted">Files are processed on this device · maximum 10 MB</small></div><div id="import-map"></div><div id="import-preview"></div><div class="modal-actions"><button id="import-confirm" class="primary" disabled>Import students</button></div>`,()=>{$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Use a file smaller than 10 MB.');importBook=XLSX.read(await file.arrayBuffer(),{type:'array',cellText:true});$('#import-map').innerHTML=`<label style="margin-top:18px">Worksheet<select id="import-sheet">${options(importBook.SheetNames.map(n=>[n,n]),importBook.SheetNames[0])}</select></label><label>Header row<input id="header-row" type="number" min="1" max="500" value="1"></label><div id="column-map"></div>`;$('#import-sheet').onchange=mapColumns;$('#header-row').onchange=mapColumns;mapColumns();}catch(err){formError(err.message);}};$('#import-confirm').onclick=()=>{if(!importPreview.length)return;const c=currentClass();let count=0;for(const item of importPreview){let s=db.students.find(s=>s.studentId===item.studentId);if(!s){s={...item,id:uid()};db.students.push(s);}if(!c.students.includes(s.id)){c.students.push(s.id);count++;}}save(`${count} students enrolled`);close();render();};});}
function mapColumns(){const rows=XLSX.utils.sheet_to_json(importBook.Sheets[$('#import-sheet').value],{header:1,defval:'',raw:false});const row=+$('#header-row').value-1;const headers=rows[row]||[];importRows=rows.slice(row+1).filter(r=>r.some(v=>String(v).trim()));const norm=s=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'');const fields=[['name','Full name',/fullname|studentname|name/],['studentId','Student ID',/studentid|idnumber|studentnumber|^id$|ssn/],['section','Section',/section/],['email','Email (optional)',/email/],['sex','Sex (optional)',/^sex$|gender/]];$('#column-map').innerHTML=fields.map(([key,label,re])=>`<label>${label}<select data-map="${key}">${options([['','— Select column —'],...headers.map((h,i)=>[i,`${XLSX.utils.encode_col(i)} · ${h||'(blank)'}`])],headers.findIndex(h=>re.test(norm(h)))<0?'':headers.findIndex(h=>re.test(norm(h))))}</select></label>`).join('');document.querySelectorAll('[data-map]').forEach(s=>s.onchange=previewImport);previewImport();}
function previewImport(){const mapping=Object.fromEntries([...document.querySelectorAll('[data-map]')].map(e=>[e.dataset.map,e.value]));$('#import-confirm').disabled=true;importPreview=[];if(mapping.name===''||mapping.studentId===''){$('#import-preview').innerHTML='<p>Select full name and student ID columns to preview.</p>';return;}const seen=new Set();let invalid=0,duplicate=0;for(const row of importRows){const item=Object.fromEntries(Object.entries(mapping).map(([k,i])=>[k,i===''?'':String(row[+i]??'').trim()]));item.sex=/^(m|male)$/i.test(item.sex)?'M':/^(f|female)$/i.test(item.sex)?'F':'';if(!item.section)item.section=currentClass().section;if(!item.name||!item.studentId){invalid++;continue;}if(seen.has(item.studentId)){duplicate++;continue;}seen.add(item.studentId);if(item.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(item.email)){invalid++;continue;}importPreview.push(item);}$('#import-preview').innerHTML=`<p>${importPreview.length} valid rows · ${invalid} invalid · ${duplicate} duplicate IDs skipped</p><div class="import-preview"><table><thead><tr><th>Full name</th><th>Student ID</th><th>Section</th></tr></thead><tbody>${importPreview.slice(0,8).map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.studentId)}</td><td>${esc(s.section)}</td></tr>`).join('')}</tbody></table></div><p>Preview shows the first 8 rows. Existing profiles will be enrolled without overwriting their details. Leading zeros are preserved when stored as text or formatted in Excel.</p>`;$('#import-confirm').disabled=!importPreview.length;}
function download(name,text,type='application/json'){const blob=new Blob([type==='text/csv'?'\uFEFF':'',text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function gradeRows(c){return [['fullname','section','student_id','subject','quarter','weighted_percentage','grade','status'],...c.students.map(student).map(s=>{const g=grade(db,c,s.id,quarter);return [s.name,s.section,s.studentId,c.name,quarter,g.percent==null?'':g.percent.toFixed(2),g.final==null?'':g.final.toFixed(2),g.final==null?'INCOMPLETE':'COMPLETE'];})];}
function exportModal(){const c=currentClass();if(!c)return;const rows=gradeRows(c);modal('Export student grades',`<p>${esc(c.name)} · ${esc(c.section)} · Quarter ${quarter}</p><div class="info">Includes full name, section, and student ID, plus the grade context. Confirm the official database’s column requirements before importing.</div><div class="import-preview"><table><thead><tr>${rows[0].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.slice(1,5).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="modal-actions"><button id="export-csv" class="primary">Download ${c.students.length} rows</button></div>`,()=>{$('#export-csv').onclick=()=>{download(`${c.section}-Q${quarter}-grades.csv`,csv(rows),'text/csv');close();toast('Grade export downloaded');};});}
function exportAdviser(){const cset=db.classes.filter(c=>c.section===db.adviserSection);download(`${db.adviserSection}-Q${quarter}-adviser.csv`,csv([['fullname','section','student_id',...cset.map(c=>c.name),'gwa'],...allStudents(cset).map(s=>[s.name,s.section,s.studentId,...cset.map(c=>formatGrade(grade(db,c,s.id,quarter).final)),formatGrade(gwa(db,cset,s.id,quarter))])]),'text/csv');}
function noteModal(id){modal('Intervention note',`<form id="dialog-form"><p>${esc(student(id).name)} · Quarter ${quarter}</p><label>Actions, observations, and next steps<textarea name="note" maxlength="3000" placeholder="e.g. Agreed to submit missing exercises by Friday…">${esc(db.notes[id]?.[quarter]||'')}</textarea></label>${formActions('Save note')}</form>`,()=>wireForm(f=>{db.notes[id]??={};db.notes[id][quarter]=f.get('note');save('Intervention note saved');close();render();}));}
function printDoc(title,body){$('#print-area').innerHTML=`<p>Republic of the Philippines · Department of Science and Technology<br><strong>PHILIPPINE SCIENCE HIGH SCHOOL — BICOL REGION CAMPUS</strong><br>Tagongtong, Goa, Camarines Sur 4422</p><h1>${title}</h1><p>School year ${esc(db.year)} · Quarter ${quarter} · ${dateFmt(today())}</p>${body}<p class="signature">Prepared by: ${esc(db.teacher)}<br><br>Signature: ___________________________</p>`;window.print();}
function slipModal(id){modal('Generate a call slip',`<form id="dialog-form"><p>${esc(student(id).name)} · ${esc(student(id).section)}</p><label>Purpose<select name="purpose">${options(['Academic Performance Conference','Consultation','Remedial Session','Behavior Conference','Interview / Talk'].map(x=>[x,x]),'Academic Performance Conference')}</select></label><div class="form-row"><label>Meeting date<input name="date" type="date" value="${today()}" required></label><label>Time<input name="time" type="time" required></label></div><label>Venue<input name="venue" placeholder="e.g. Computer laboratory" required></label>${formActions('Print call slip')}</form>`,()=>wireForm(f=>{const s=student(id),missing=missingFor(id);close();printDoc('ACADEMIC AND BEHAVIOR CONFERENCE — CALL SLIP',`<p><strong>Student:</strong> ${esc(s.name)}<br><strong>Section:</strong> ${esc(s.section)}<br><strong>Student ID:</strong> ${esc(s.studentId)}</p><p>Please come for: ${esc(f.get('purpose'))}<br>Date: ${esc(f.get('date'))} · Time: ${esc(f.get('time'))}<br>Venue: ${esc(f.get('venue'))}</p><table><thead><tr><th>Missing output</th><th>Subject</th><th>Deadline</th></tr></thead><tbody>${missing.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(db.classes.find(c=>c.id===a.classId).name)}</td><td>${a.due}</td></tr>`).join('')||'<tr><td colspan="3">No overdue outputs recorded.</td></tr>'}</tbody></table><p class="signature">Student acknowledgment: ___________________________</p>`);}));}
function emailModal(id){const s=student(id),missing=missingFor(id);const subject=`Quarter ${quarter} · Academic follow-up`;const text=`Hello ${s.name},\n\nLet’s check in on your progress for Quarter ${quarter}.\n${missing.length?'Please follow up on these outstanding outputs:\n'+missing.map(a=>`• ${a.name} (${db.classes.find(c=>c.id===a.classId).name}) — due ${a.due}`).join('\n'):'Please arrange a consultation so we can discuss your progress.'}\n\nLet me know if you need help or additional support.\n\n${db.teacher}\nPSHS Bicol Region Campus`;modal('Review follow-up email',`<form id="dialog-form"><p>This opens a draft in your email app. Review it there before sending. No email is sent automatically.</p><label>To<input name="email" type="email" value="${esc(s.email)}" required></label><label>Subject<input name="subject" value="${esc(subject)}" required></label><label>Message<textarea name="body" style="min-height:200px" required>${esc(text)}</textarea></label>${formActions('Open email draft')}</form>`,()=>wireForm(f=>{location.href=`mailto:${encodeURIComponent(f.get('email'))}?subject=${encodeURIComponent(f.get('subject'))}&body=${encodeURIComponent(f.get('body'))}`;close();}));}
function printGrades(){navigate('grading-sheet');}
function printSubmissions(){printDoc('SUBMISSION & INTERVENTION REPORT',`<table><thead><tr><th>Student</th><th>Section</th><th>Missing outputs</th><th>Grade concerns</th><th>Intervention</th></tr></thead><tbody>${attention().filter(x=>sectionFilter==='all'||x.s.section===sectionFilter).map(({s,missing,low})=>`<tr><td>${esc(s.name)}</td><td>${esc(s.section)}</td><td>${missing.map(a=>esc(a.name)).join('<br>')||'None'}</td><td>${low.map(c=>esc(c.name)).join('<br>')||'None'}</td><td>${esc(db.notes[s.id]?.[quarter]||'')}</td></tr>`).join('')}</tbody></table>`);}
function vaultModal(){modal('Set up your secure workspace',`<form id="dialog-form"><p>Choose a passphrase to encrypt your local database. You’ll use it to unlock this device and restore your encrypted records on another device.</p><label>Passphrase (at least 12 characters)<input type="password" name="pass" minlength="12" required autocomplete="new-password"></label><label>Confirm passphrase<input type="password" name="confirm" minlength="12" required autocomplete="new-password"></label><label class="checkbox"><input type="checkbox" name="empty" checked>Start with an empty workspace</label><p>Keep your passphrase safe. It cannot be reset or recovered. If your signed-in account already has cloud records, enter that vault’s passphrase to restore them.</p>${formActions('Create / restore encrypted vault')}</form>`,()=>wireForm(async f=>{if(f.get('pass')!==f.get('confirm'))throw Error('Passphrases do not match.');const initial=f.get('empty')?{...db,students:[],classes:[],assignments:[],scores:{},notes:{}}:db;db=await vault.enable(initial,f.get('pass'));classId=db.classes[0]?.id||'';close();render();toast('Encrypted workspace ready');}));}
async function backup(){if(!vault.isEnabled())return toast('Enable secure storage first.');download(`pisay-encrypted-backup-${today()}.json`,await vault.encryptedBackup());}
function restoreModal(){modal('Restore encrypted backup',`<form id="dialog-form"><p>Restoring replaces this device’s current workspace. Download an encrypted backup of the current version first if needed.</p><label>Backup file<input type="file" name="file" accept=".json" required></label><label>Backup passphrase<input type="password" name="pass" required></label>${formActions('Restore backup')}</form>`,()=>wireForm(async f=>{db=await vault.restoreBackup(await f.get('file').text(),f.get('pass'));classId=db.classes[0]?.id||'';close();render();}));}
function cloudReview(){modal('Review the cloud version',`<form id="dialog-form"><p>To resolve a conflict, first download your local encrypted backup. Loading the cloud version replaces this device’s records; the backup preserves your offline changes for later review.</p><button type="button" id="conflict-backup">Download local backup</button><label style="margin-top:18px">Vault passphrase<input type="password" name="pass" required></label><label class="checkbox"><input type="checkbox" required>I have saved my local work and want to load the cloud version</label>${formActions('Load cloud version')}</form>`,()=>{$('#conflict-backup').onclick=backup;wireForm(async f=>{db=await vault.cloudVersion(f.get('pass'));classId=db.classes[0]?.id||'';close();render();});});}
vault.setStatusListener(s=>{if($('#sync-status'))$('#sync-status').innerHTML=`<span class="dot"></span>${esc(s)}`;if($('#storage-status'))$('#storage-status').textContent=s;});
vault.setRemoteListener(data=>{db=data;if(!db.classes.some(c=>c.id===classId))classId=db.classes[0]?.id||'';if($('#modal').open)close();render();toast('Changes from your other device have synced.');});
let lastActivity=Date.now();['pointerdown','keydown','touchstart'].forEach(name=>addEventListener(name,()=>lastActivity=Date.now(),{passive:true}));setInterval(()=>{if(vault.isEnabled()&&Date.now()-lastActivity>15*60*1000)vault.lock();},30000);
async function start(){if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>toast('Offline app caching is unavailable in this browser.'));try{const existing=await vault.inspectVault();if(existing){$('#app').innerHTML=`<div style="max-width:440px;margin:13vh auto;padding:25px"><div class="brand"><div class="brand-mark">p</div><div><strong>pisay.</strong><small>YOUR SECURE WORKSPACE</small></div></div><div class="panel"><h1 style="font-size:25px">Welcome back.</h1><p class="notes" style="margin:15px 0">Unlock your encrypted class records. Your passphrase stays on this device and is never sent to the server.</p><form id="unlock-form"><label>Vault passphrase<input id="unlock-pass" type="password" required autocomplete="current-password" style="display:block;width:100%;padding:13px;margin:10px 0 18px;border:1px solid #d9e3d4;border-radius:8px"></label><button class="primary" style="width:100%">Unlock workspace</button><p id="unlock-error" class="notes" style="margin-top:12px;color:#a65f50"></p></form></div></div>`;$('#unlock-form').onsubmit=async e=>{e.preventDefault();try{db=await vault.unlock($('#unlock-pass').value);classId=db.classes[0]?.id||'';render();}catch(err){$('#unlock-error').textContent=err.message;}};return;}}catch{toast('Local storage is unavailable. Demo changes will not be saved.');}render();}
start();

function gradingSheetPage(){const c=currentClass();if(!c)return empty('Create a class to prepare its grading sheet','Add your class, import students, and enter quarter scores.','Add class','add-class');const settings={...db.reportSettings,adviser:c.adviser||'',demo:!vault.isEnabled()},m=gradingSheetModel(db,c,quarter,settings);return `${heading('Quarterly grading sheet',`Prepare, download, and sign · ${QUARTER_NAMES[quarter-1]} quarter`,button('Download PDF','sheet-pdf','primary','download')+button('Download Excel','sheet-xlsx','','download')+button('Both formats','sheet-both'))}<div class="toolbar">${classSelect()}<small class="muted">Use the quarter selector above to change the grading period.</small></div><form id="sheet-settings" class="panel sheet-settings"><label>Class adviser<input name="adviser" value="${esc(settings.adviser)}" placeholder="Full name"></label><label>Subject teacher<input name="teacher" value="${esc(settings.teacher||db.teacher)}" placeholder="Full name"></label><label>Unit Head<input name="unitHead" value="${esc(settings.unitHead||'')}" placeholder="Full name"></label><label>CID Chief<input name="cidChief" value="${esc(settings.cidChief||'')}" placeholder="Full name"></label><label>Document code<input name="documentCode" value="${esc(settings.documentCode||'')}" placeholder="e.g. R-07-CID(CS)-203B"></label><label>Paper size<select name="paper">${options([['legal','Legal · portrait (8.5 × 14 in)'],['a4','A4 · portrait'],['a4-landscape','A4 · landscape']],settings.paper||'legal')}</select></label></form><div class="info" style="margin-top:16px">PDF and Excel downloads are generated on your device and work offline. Sign the PDF after downloading, or print and sign by hand. Signature spaces are left blank. ${m.draft?'<strong>This sheet is marked DRAFT because it contains incomplete grades or demonstration data.</strong>':''}</div><div class="sheet-preview-scroll" id="sheet-preview">${sheetPreview(m)}</div>`;}
const QUARTER_NAMES=['First','Second','Third','Fourth'];
async function exportSheet(format){const c=currentClass();if(!c)return;const m=gradingSheetModel(db,c,quarter,{...db.reportSettings,adviser:c.adviser||'',demo:!vault.isEnabled()});if(!m.rows.length)return toast('Add students before exporting a grading sheet.');toast('Preparing your grading sheet…');try{const assets={pshs:await (await fetch('/branding/pshs.jpg')).arrayBuffer(),dost:await (await fetch('/branding/dost.jpg')).arrayBuffer()};if(format==='pdf'||format==='both'){const bytes=await generatePdf(m,window.PDFLib,assets);saveDownload(bytes,filename(m,'pdf'),'application/pdf');}if(format==='xlsx'||format==='both'){const bytes=await generateXlsx(m,window.ExcelJS,assets);saveDownload(bytes,filename(m,'xlsx'),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}toast(format==='both'?'PDF and Excel downloads prepared':'Grading sheet downloaded');}catch(e){toast('Export failed: '+e.message);}}

function studentLink(s){return `<button class="student-link" data-profile="${esc(s.id)}" title="View student performance">${esc(s.name)}</button>`;}
function profileReport(){
 const s=student(profileId);if(!s)return '<p>Student no longer available.</p>';
 const p=studentPerformance(db,s.id,quarter,today());
 return `<div class="profile-report"><p><strong>${esc(s.name)}</strong> · ${esc(s.studentId)} · ${esc(s.section)} · Quarter ${quarter}</p><div class="info">All enrolled subjects available in this workspace. GWA waits for complete grades. Low-score flags mean below 60% of raw points, before Base 50 or component weighting; they are review indicators.</div><div class="stats">${stat('Quarter GWA',formatGrade(p.gwa),'Completed subject grades','chart')}${stat('Missing outputs',p.missing,'Overdue or marked missing','file',true)}${stat('Low scores',p.low,'Below 60% of raw points','chart',true)}${stat('Awaiting marking',p.ungraded,`${p.pending} outputs not yet due`,'clock')}</div><h2>Four-quarter subject summary</h2><div class="table-wrap"><table><thead><tr><th>Subject</th>${[1,2,3,4].map(q=>`<th>Q${q}</th>`).join('')}</tr></thead><tbody>${p.subjects.map(x=>`<tr><td>${esc(x.class.name)}<span class="sub">${esc(x.class.section)}</span></td>${x.quarters.map(g=>`<td>${formatGrade(g)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${p.subjects.map(x=>`<section class="panel profile-subject"><h2>${esc(x.class.name)}</h2><p>Quarter grade: <strong>${formatGrade(x.grade.final)}</strong> · Weighted total: ${x.grade.percent==null?'—':x.grade.percent.toFixed(2)+'%'}${!x.grade.complete?' (provisional)':''}</p><p>${x.grade.reason?esc(x.grade.reason):'Quarter grade complete.'} ${quarter>1&&x.class.method!=='independent'?'This cumulative grade includes the previous quarter.':''}</p><p>${x.outputs.filter(a=>a.missing).length} missing · ${x.outputs.filter(a=>a.low).length} low scores · ${x.outputs.filter(a=>a.ungraded).length} awaiting marking</p><div class="table-wrap"><table><thead><tr><th>Assessment component</th><th>Weight</th><th>Component %</th><th>Contribution</th></tr></thead><tbody>${x.components.map(c=>`<tr><td>${esc(c.name)}${!c.complete?'<span class="sub">Incomplete / provisional</span>':''}</td><td>${c.weight}%</td><td>${c.percent==null?'—':c.percent.toFixed(2)}</td><td>${c.weighted==null?'—':c.weighted.toFixed(2)}</td></tr>`).join('')}</tbody></table></div><div class="table-wrap"><table><thead><tr><th>Output</th><th>Due date</th><th>Status</th><th>Score</th><th>Review</th></tr></thead><tbody>${x.outputs.map(a=>`<tr><td>${esc(a.name)}<span class="sub">${esc(a.category)}</span></td><td>${dateFmt(a.due)}</td><td>${esc(a.status)}</td><td>${a.score==null?'—':`${a.score} / ${a.points} (${a.percent.toFixed(1)}%)`}</td><td>${[a.missing?'Missing submission':'',a.pending?'Not yet due':'',a.ungraded?'Submitted, awaiting score':'',a.low?'Low score':'',a.status==='excused'?'Excluded from grade':''].filter(Boolean).join(' · ')||'—'}</td></tr>`).join('')||'<tr><td colspan="5">No outputs recorded for this quarter.</td></tr>'}</tbody></table></div></section>`).join('')||'<p>No enrolled subjects available.</p>'}<section class="panel profile-subject"><h2>Intervention note · Q${quarter}</h2><p class="profile-note">${esc(db.notes[s.id]?.[quarter]||'No intervention note recorded.')}</p></section></div>`;
}
function studentProfilePage(){const s=student(profileId);if(!s)return empty('Student unavailable','Return to the student list.','Back','profile-back');return `${heading(esc(s.name),'Individual student performance',button('Back to list','profile-back')+button('Print / Save PDF','print-profile','','file'))}<div class="toolbar"><button data-note="${esc(s.id)}">Edit intervention note</button><button data-slip="${esc(s.id)}">Call slip</button><button data-email="${esc(s.id)}">Email follow-up</button></div>${profileReport()}`;}

function studentDirectory(cset){return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Section</th><th>Subjects</th><th>Quarter GWA</th><th>Missing outputs</th></tr></thead><tbody>${allStudents(cset).map(s=>`<tr><td>${studentLink(s)}<span class="sub">${esc(s.studentId)}</span></td><td>${esc(s.section)}</td><td>${cset.filter(c=>c.students.includes(s.id)).length}</td><td>${formatGrade(gwa(db,cset,s.id,quarter))}</td><td>${missingFor(s.id,cset).length}</td></tr>`).join('')}</tbody></table></div>`;}
